wpcloud/graph.css:
& {
	padding: 1em;
	box-sizing: border-box;
	margin-bottom: 0 !important;

	/* Horizontal Bar Graph Styles */
}

& .uplot {
	width: 100%;
}

& .uplot .u-wrap {
	width: 100%;
}

& .u-title {
	padding-bottom: 10px;
	margin: 0;
	text-align: left;
	font-size: 18px;
	font-weight: bold;
	color: var(--pico-color);
}

& .wpcloud-horizontal-bar-graph-title {
	padding-bottom: 10px;
	margin: 0;
	text-align: left;
	font-size: 18px;
	font-weight: bold;
	color: var(--pico-color);
}

& .u-legend {

	/* Allow the legend to grow and not be clipped */ /* Reduce bottom space */ /* Reduce bottom space */
}

& .u-legend .u-marker {
	height: .25em !important;
	border-radius: 0.125em;
}

& .u-legend {
	max-height: none !important;
	overflow: visible !important;
	margin-bottom: 0 !important;
	padding-bottom: 0 !important;
}

	/* Style legend table */

& .u-legend table {
	width: 100%;
	margin-bottom: 0; /* Reduce bottom space */
}

	/* When many series, allow wrapping to multiple columns */

& .u-legend.u-legend-many {
	display: flex;
	flex-wrap: wrap;
}

& .u-legend.u-legend-many tr {
	width: auto;
	margin-right: 10px;
}

	/* Right-positioned legend styles - these are now applied via JavaScript in the legendPositionPlugin */

& .u-legend[data-position="right"] {
	/* Styles are applied directly via JavaScript for better compatibility */
	background-color: rgba(255, 255, 255, 0.8);
	border-radius: 4px;
	border: 1px solid #ddd;
}

	/* Container adjustments for right legend */

& .u-wrap {
	position: relative;
}

	/* Flex layout for graph with side legend */

& .wpcloud-uplot-graph {
	width: 100%;
	position: relative;
	box-sizing: border-box;
}

& .wpcloud-uplot-graph--with-side-legend {
	display: flex;
	flex-direction: row;
	align-items: stretch;
	width: 100%;
}

& .wpcloud-uplot-graph__chart-container {
	flex: 1;
	min-width: 0; /* Prevent flex item from overflowing */
}

	/* Apply width constraints only to charts with side legends */

& .wpcloud-uplot-graph--with-side-legend .wpcloud-uplot-graph__chart-container {
	max-width: calc(100% - 130px); /* Account for legend width (110px) + margin (20px) */
	width: calc(100% - 130px); /* Force width to be fixed */
}

	/* Force uPlot to respect container width only when side legend is present */

& .wpcloud-uplot-graph--with-side-legend .wpcloud-uplot-graph__chart-container .uplot {
	width: 100% !important;
	max-width: 100% !important;
}

& .wpcloud-uplot-graph--with-side-legend .wpcloud-uplot-graph__chart-container .u-wrap {
	width: 100% !important;
	max-width: 100% !important;
}

	/* Add overflow hidden to prevent elements from flowing outside their container */

& .wpcloud-uplot-graph--with-side-legend .wpcloud-uplot-graph__chart-container {
	overflow: hidden;
}

& .wpcloud-uplot-graph__legend-container {
	width: 110px;
	flex-shrink: 0;
	margin-left: 20px;
	align-self: flex-start; /* Align to the top of the container */
}

	/* Match the height of the legend container to the uPlot element */

& .wpcloud-uplot-graph--with-side-legend .wpcloud-uplot-graph__legend-container {
	height: 456px; /* Fixed height that matches typical uPlot height */
	max-height: 456px; /* Set a maximum height that matches typical uPlot height */
	overflow: hidden; /* Ensure the container doesn't overflow */
}

	/* When the uPlot element is present, match its height exactly */

& .wpcloud-uplot-graph--with-side-legend .uplot + .wpcloud-uplot-graph__legend-container {
	height: 100%; /* Match the height of the graph container */
}

	/* Custom Side Legend Styles */

& .wpcloud-side-legend {
	height: 100%;
	padding: 10px;
	box-sizing: border-box;
	overflow-y: auto; /* Make y-overflow scrollable */
	scrollbar-width: none !important; /* Firefox */
	-ms-overflow-style: none !important; /* IE and Edge */
}

	/* Add some spacing at the top of the items to replace the removed heading */

& .wpcloud-side-legend__items {
	padding-top: 5px;
}

	/* Hide scrollbar for Chrome, Safari and Opera */

& .wpcloud-side-legend::-webkit-scrollbar {
	width: 0 !important;
	height: 0 !important;
	background-color: transparent !important;
	display: none !important;
}

& .wpcloud-side-legend::-webkit-scrollbar-thumb {
	width: 0 !important;
	height: 0 !important;
	background-color: transparent !important;
	display: none !important;
}

& .wpcloud-side-legend::-webkit-scrollbar-track {
	width: 0 !important;
	height: 0 !important;
	background-color: transparent !important;
	display: none !important;
}

& .wpcloud-side-legend__title {
	font-weight: bold;
	margin-bottom: 10px;
	font-size: 14px;
}

& .wpcloud-side-legend__items {
	display: flex;
	flex-direction: column;
	gap: 8px;
}

& .wpcloud-side-legend__item {
	display: flex;
	align-items: center;
	gap: 6px;
	cursor: default;
}

& .wpcloud-side-legend__marker {
	width: 12px;
	height: 12px;
	border-radius: 2px;
}

& .wpcloud-side-legend__label {
	font-size: 12px;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	color: var(--pico-muted-color, #666);
	transition: color 0.2s ease;
}

& .wpcloud-side-legend__item:hover .wpcloud-side-legend__label {
	color: var(--pico-color, #000);
	font-weight: 500;
}

& .u-series th {
	background: none;
}

& .u-series td {
	background: none;
}

& .wpcloud-horizontal-bar-graph {
	display: flex;
	flex-direction: column;
	width: 100%;
	padding: 20px;
	box-sizing: border-box;
}

& .wpcloud-horizontal-bar-graph-container {
	display: flex;
	flex-direction: column;
	width: 100%;
	gap: 8px;
	box-sizing: border-box;
}

& .wpcloud-horizontal-bar-graph-row {
	display: grid;
	grid-template-columns: minmax(150px, 25%) 1fr 70px;
	align-items: center;
	gap: 10px;
	width: 100%;
	height: 30px;
}

& .wpcloud-horizontal-bar-graph-label {
	font-size: 0.9rem;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	padding-left: 5px;
}

& .wpcloud-horizontal-bar-graph-bar-container {
	height: 20px;
	background-color: rgba(0, 0, 0, 0.3);
	border-radius: 2px;
	overflow: hidden;
}

& .wpcloud-horizontal-bar-graph-bar {
	height: 100%;
	border-radius: 2px;
	transition: width 0.3s ease;
}

& .wpcloud-horizontal-bar-graph-value {
	font-size: 0.9rem;
	font-weight: 600;
	text-align: right;
	padding-right: 5px;
}

	@media (prefers-color-scheme: dark) {
& {
	border-radius: var(--pico-border-radius);
	border: var(--pico-border-width) solid var(--pico-form-element-border-color);
	background-color: var(--pico-form-element-background-color);
	color: var(--pico-form-element-placeholder-color);
}

& .wpcloud-horizontal-bar-graph-bar-container {
	background-color: rgba(255, 255, 255, 0.1);
}

& .wpcloud-tooltip {
	background-color: rgba(255, 255, 255, 0.8);
	color: black;
}
}

wpcloud/metrics.css:
& .wpcloud-graph-tooltip {
	background-color: var(--pico-secondary-background);
	color: var(--pico-color);
	padding: 4px 8px;
	border-radius: 4px;
	font-size: 0.8rem;
}

	@media (prefers-color-scheme: light) {
& .wpcloud-graph-tooltip {
	border: var(--pico-border-width) solid var(--pico-form-element-border-color);
	background-color: var(--pico-form-element-background-color);
	color: var(--pico-form-element-placeholder-color);
	padding: 2px 8px;
}
}
